class Solution {
    public: int largestMagicSquare(vector<vector<int>>& grid){
        int rows=grid.size(),cols=grid[0].size();
        vector<vector<int>> row(rows,vector<int>(cols+1)),col(rows+1,vector<int>(cols));
        for(int r=0;r<rows;++r)for(int c=0;c<cols;++c){
            row[r][c+1]=row[r][c]+grid[r][c];
            col[r+1][c]=col[r][c]+grid[r][c];
        }
        for(int size=min(rows,cols);size>=1;--size)for(int top=0;top+size<=rows;++top)for(int left=0;left+size<=cols;++left){
            int target=row[top][left+size]-row[top][left];
            bool valid=true;
            for(int offset=0;offset<size&&valid;++offset)valid=row[top+offset][left+size]-row[top+offset][left]==target&&col[top+size][left+offset]-col[top][left+offset]==target;
            int first=0,second=0;
            for(int offset=0;offset<size;++offset){
                first+=grid[top+offset][left+offset];
                second+=grid[top+offset][left+size-1-offset];
            }
            if(valid&&first==target&&second==target)return size;
        }
        return 1;
    }
};
